import { useState, useEffect } from 'react';
import client from '../../api/client';
import './Productos.css';

const formatCOP = (v) =>
  new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v || 0);

const empty = {
  nombre: '', descripcion: '', precio: '', costo: '',
  categoriaId: '', stock: '', trackInventory: false,
  unidadVenta: 'unidad', codigoInterno: '', badge: '',
};

export default function Productos() {
  const [productos, setProductos]   = useState([]);
  const [categorias, setCategorias] = useState([]);
  const [busqueda, setBusqueda]     = useState('');
  const [form, setForm]             = useState(empty);
  const [editId, setEditId]         = useState(null);
  const [showForm, setShowForm]     = useState(false);
  const [loading, setLoading]       = useState(false);

  useEffect(() => { cargar(); }, []);

  const cargar = async () => {
    const [pRes, cRes] = await Promise.all([
      client.get('/api/productos'),
      client.get('/api/categorias'),
    ]);
    setProductos(pRes.data);
    setCategorias(cRes.data);
  };

  const filtrados = productos.filter(p =>
    p.nombre?.toLowerCase().includes(busqueda.toLowerCase()) ||
    p.codigoInterno?.toLowerCase().includes(busqueda.toLowerCase())
  );

  const abrirNuevo = () => {
    setForm(empty);
    setEditId(null);
    setShowForm(true);
  };

  const abrirEditar = (p) => {
    setForm({
      nombre: p.nombre || '', descripcion: p.descripcion || '',
      precio: p.precio || '', costo: p.costo || '',
      categoriaId: p.categoriaId || '', stock: p.stock ?? '',
      trackInventory: p.trackInventory || false,
      unidadVenta: p.unidadVenta || 'unidad',
      codigoInterno: p.codigoInterno || '', badge: p.badge || '',
    });
    setEditId(p.id);
    setShowForm(true);
  };

  const guardar = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const payload = {
        ...form,
        precio: parseFloat(form.precio),
        costo:  parseFloat(form.costo) || 0,
        stock:  parseFloat(form.stock) || 0,
        categoriaId: form.categoriaId || null,
      };
      if (editId) {
        await client.put(`/api/productos/${editId}`, payload);
      } else {
        await client.post('/api/productos', payload);
      }
      setShowForm(false);
      cargar();
    } catch (err) {
      alert(err.response?.data?.error || 'Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  const eliminar = async (id) => {
    if (!window.confirm('¿Eliminar este producto?')) return;
    await client.delete(`/api/productos/${id}`);
    cargar();
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">📦 Productos</h1>
        <button className="btn btn-primary" onClick={abrirNuevo}>+ Nuevo producto</button>
      </div>

      <div className="card" style={{ marginBottom: 16 }}>
        <input
          placeholder="Buscar por nombre o código..."
          value={busqueda}
          onChange={e => setBusqueda(e.target.value)}
        />
      </div>

      <div className="card table-wrap">
        <table>
          <thead>
            <tr>
              <th>Nombre</th>
              <th>Categoría</th>
              <th>Precio</th>
              <th>Costo</th>
              <th>Stock</th>
              <th>Código</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {filtrados.map(p => (
              <tr key={p.id}>
                <td>
                  <strong>{p.nombre}</strong>
                  {p.badge && <span className="badge badge-blue" style={{ marginLeft: 6 }}>{p.badge}</span>}
                </td>
                <td>{categorias.find(c => c.id === p.categoriaId)?.nombre || <span style={{ color: '#bbb' }}>—</span>}</td>
                <td>{formatCOP(p.precio)}</td>
                <td>{formatCOP(p.costo)}</td>
                <td>
                  {p.trackInventory
                    ? <span className={`badge ${p.stock < 5 ? 'badge-red' : 'badge-green'}`}>{p.stock}</span>
                    : <span style={{ color: '#bbb' }}>—</span>}
                </td>
                <td>{p.codigoInterno || <span style={{ color: '#bbb' }}>—</span>}</td>
                <td>
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button className="btn btn-secondary" style={{ padding: '4px 10px', fontSize: '.78rem' }}
                      onClick={() => abrirEditar(p)}>Editar</button>
                    <button className="btn btn-danger" style={{ padding: '4px 10px', fontSize: '.78rem' }}
                      onClick={() => eliminar(p.id)}>Eliminar</button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal form */}
      {showForm && (
        <div className="modal-overlay">
          <div className="modal-box modal-wide">
            <h3>{editId ? 'Editar producto' : 'Nuevo producto'}</h3>
            <form onSubmit={guardar} className="producto-form">
              <div className="form-grid">
                <div className="field">
                  <label>Nombre *</label>
                  <input required value={form.nombre} onChange={e => setForm({ ...form, nombre: e.target.value })} />
                </div>
                <div className="field">
                  <label>Código interno</label>
                  <input value={form.codigoInterno} onChange={e => setForm({ ...form, codigoInterno: e.target.value })} />
                </div>
                <div className="field">
                  <label>Precio de venta *</label>
                  <input required type="number" min="0" value={form.precio} onChange={e => setForm({ ...form, precio: e.target.value })} />
                </div>
                <div className="field">
                  <label>Costo</label>
                  <input type="number" min="0" value={form.costo} onChange={e => setForm({ ...form, costo: e.target.value })} />
                </div>
                <div className="field">
                  <label>Categoría</label>
                  <select value={form.categoriaId} onChange={e => setForm({ ...form, categoriaId: e.target.value })}>
                    <option value="">— Sin categoría —</option>
                    {categorias.map(c => <option key={c.id} value={c.id}>{c.nombre}</option>)}
                  </select>
                </div>
                <div className="field">
                  <label>Badge</label>
                  <input placeholder="Ej: Nuevo, Popular" value={form.badge} onChange={e => setForm({ ...form, badge: e.target.value })} />
                </div>
                <div className="field">
                  <label>Stock inicial</label>
                  <input type="number" min="0" value={form.stock} onChange={e => setForm({ ...form, stock: e.target.value })} />
                </div>
                <div className="field">
                  <label>Unidad de venta</label>
                  <select value={form.unidadVenta} onChange={e => setForm({ ...form, unidadVenta: e.target.value })}>
                    <option value="unidad">Unidad</option>
                    <option value="medida">Medida</option>
                  </select>
                </div>
              </div>
              <div className="field" style={{ marginTop: 4 }}>
                <label>Descripción</label>
                <textarea rows={2} value={form.descripcion} onChange={e => setForm({ ...form, descripcion: e.target.value })} />
              </div>
              <label className="check-label">
                <input type="checkbox" checked={form.trackInventory}
                  onChange={e => setForm({ ...form, trackInventory: e.target.checked })} />
                Controlar inventario
              </label>
              <div className="form-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowForm(false)}>Cancelar</button>
                <button type="submit" className="btn btn-primary" disabled={loading}>
                  {loading ? 'Guardando...' : 'Guardar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
